    /// <summary>
    /// Application start up calls this method. Initialise the multi select base enum lookups here.
    /// </summary>
    public void initLookupValueTable()
    {
        ttsbegin;

        this.initMETVendSitePOSetup();
        this.initMETVendSiteSendMethodCampaign();
        this.initMetVendDistributionMethod();
        this.initMETPOSubMode();
        this.initMETPOChngSubMode();//MPJ_27166_BuyPOFSDEnhancements
      
        ttscommit;
    }

/// <summary>
/// Init the base enum
/// </summary>
private void initMETVendSitePOSetup()
{
    SysDictEnum sysDictEnum = new SysDictEnum(enumNum(METVendSitePOSetup));
    this.initFromBaseEnum(sysDictEnum);
}

/// <summary>
/// Init the base enum
/// </summary>
private void initMETVendSiteSendMethodCampaign()
{
    SysDictEnum sysDictEnum = new SysDictEnum(enumNum(METVendSiteSendMethodCampaign));        
    this.initFromBaseEnum(sysDictEnum);
}

/// <summary>
/// Init the base enum
/// </summary>
private void initMetVendDistributionMethod()
{
    SysDictEnum sysDictEnum = new SysDictEnum(enumNum(MetVendDistributionMethod));
    this.initFromBaseEnum(sysDictEnum);
}

/// <summary>
/// Init the base enum
/// </summary>
private void initMETPOSubMode()
{
    SysDictEnum sysDictEnum = new SysDictEnum(enumNum(METPOSubMode));
    this.initFromBaseEnum(sysDictEnum);
}

/// <summary>
/// MPJ_27166_BuyPOFSDEnhancements
/// Init the base enum
/// </summary>
private void initMETPOChngSubMode()
{
    SysDictEnum sysDictEnum = new SysDictEnum(enumNum(METPOChngSubMode));
    this.initFromBaseEnum(sysDictEnum);
}

  /// <summary>
  /// Iterates the given base enum and inserts values in the table
  /// </summary>
  /// <param name = "_baseEnum">The baes enum name</param>
    private void initFromBaseEnum(SysDictEnum _baseEnum)
    {
        METMultiSelectBaseEnumTable metMultiSelectBaseEnumTable;
        int i;

        for (i = 0; i < _baseEnum.values(); i++)
        {
            if (!METMultiSelectBaseEnumTable::doesEnumValueExist(_baseEnum.name(), _baseEnum.index2Value(i), _baseEnum.index2Name(i)))
            {
                metMultiSelectBaseEnumTable.clear();
                metMultiSelectBaseEnumTable.EnumName = _baseEnum.name();
                metMultiSelectBaseEnumTable.EnumValue = _baseEnum.index2Value(i);
                metMultiSelectBaseEnumTable.EnumText = _baseEnum.index2Name(i);
                metMultiSelectBaseEnumTable.insert();
            }
        }
    }
